questionvariables.text:
/* Randomly generate and calculate the initial probabilities*/
t1:rand(10)+1;/*diners had ordered all three items*/
t2:rand_with_prohib(10,25,[t1]); /* diners had ordered beer and cheesecake*/
t3:rand_with_prohib(10,25,[t1,t2]); /*diners had ordered garlic bread and cheesecake*/
t4:rand_with_prohib(10,25,[t1,t2,t3]); /*diners had ordered garlic bread and beer*/
t5:rand_with_step(35,55,1);/*diners had ordered garlic bread*/
t6:rand_with_prohib(35,55,[t5]); /*diners had ordered cheesecake*/
t7:rand_with_prohib(45,55,[t5,t6]); /*diners had ordered beer*/
Total: rand_with_step(300,700,5); /*total dinners*/
/*Number of diners who ordered two items only*/
beer_bread:t4-t1;/*Only ordered beer and  bread*/
bread_cake:t3-t1;/*Only ordered cake and  bread*/
beer_cake:t2-t1;/*only beer and cake*/   
/*Number of diners who ordered on item only*/
only_beer: t7-(beer_bread+beer_cake+t1)/*beer only*/
only_garlic: t5-(beer_bread+bread_cake+t1)/*garlic only*/
only_cake: t6-(bread_cake+beer_cake+t1)/*cake only*/

/*dinners who chose none of the items*/
t8: Total-(only_beer+only_garlic+only_cake+beer_bread+bread_cake+bread_cake+t1); 

/*model answers */
ta1: t1 / Total;
ta2: only_beer / Total;
ta3: (t4-t1)/ Total;
ta4: t8/Total;

feedbackvariables.text:
/*Node 1: check for correct answer*/

/*Node 2: mistake: decimalplaces((t7 - t4 + t1 + t3)/Total_diners,2)*/
mistake_2:decimalplaces((t7 - t4 + t1 + t3)/Total_diners,2);

/*Node 1: check for correct answer*/

/*Node 2: mistake: decimalplaces((t4+t1)/ Total_diners,2)*/
mistake_2:decimalplaces((t4+t1)/ Total_diners,2);

/*Node 1: check for correct answer*/

/*Node 2: mistake: decimalplaces( t8 +t1/ Total_diners,2)*/
mistake_2:decimalplaces( t8 +t1/ Total_diners,2);
